package com.codenzic.workspace.team.infrastructure; import com.codenzic.workspace.team.domain.Team; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface TeamRepository extends JpaRepository<Team,UUID>{List<Team> findAllByOrganizationId(UUID organizationId); List<Team> findAllByDepartmentIdAndOrganizationId(UUID departmentId,UUID organizationId); boolean existsByIdAndOrganizationId(UUID id, UUID organizationId); Optional<Team> findByIdAndOrganizationId(UUID id,UUID organizationId);}